def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Select the unique multi-cell non-background line as the source stamp.
    candidates = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start >= 2:
                candidates.append((c - start, 'h', r, start))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start >= 2:
                candidates.append((r - start, 'v', start, c))
    if not candidates:
        return [row[:] for row in grid]
    _, orient, sr, sc = max(candidates, key=lambda x: x[0])
    pattern = []
    if orient == 'h':
        pattern = [(0, i, grid[sr][sc+i]) for i in range(max(x[0] for x in candidates))]
        ph, pw = 1, len(pattern)
    else:
        pattern = [(i, 0, grid[sr+i][sc]) for i in range(max(x[0] for x in candidates))]
        ph, pw = len(pattern), 1
    # Stamp center is aligned to each isolated marker of the remaining color.
    seed = {(sr, sc+i) if orient == 'h' else (sr+i, sc) for i in range(len(pattern))}
    nonbg = Counter(grid[r][c] for r in range(h) for c in range(w)
                    if grid[r][c] != bg and (r,c) not in seed)
    if not nonbg:
        return [row[:] for row in grid]
    marker = nonbg.most_common(1)[0][0]
    ar, ac = ph//2, pw//2
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r,c) not in seed:
                for dr, dc, value in pattern:
                    rr, cc = r+dr-ar, c+dc-ac
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
